try{const preview=new URLSearchParams(location.search).get('preview')==='1';if(preview){settings=C.merge(JSON.parse(localStorage.getItem('bloom-content-preview')||'{}'));const banner=document.createElement('div');banner.textContent='DRAFT PREVIEW — these changes are not published';banner.style='position:sticky;top:0;z-index:100;background:#34212c;color:white;padding:14px;text-align:center';document.body.prepend(banner)}else{const r=await fetch(supabaseUrl+'/rest/v1/bloom_site_content?id=eq.published&select=data',{headers:{apikey:supabasePublishableKey},signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('content');const rows=await r.json();settings=C.merge(rows[0]?.data||{})}}catch{console.info('Using saved page defaults.');}
