money=value=>currency==='USD'?'US$'+(value/Number(settings.zmw_per_usd||25)).toFixed(2):'K'+Number(value).toLocaleString('en-ZM');if(!localStorage.getItem('bloom-currency'))currency=settings.default_currency==='USD'?'USD':'ZMW';if(!settings.usd_enabled)currency='ZMW';select('#currency').value=currency;select('#currency option[value="USD"]').hidden=!settings.usd_enabled;select('#services>p.notice').textContent='Prices in Zambian Kwacha. USD uses a manual rate of K'+settings.zmw_per_usd+' = US$1.';
times=function(){const date=select('#date').value,d=date?new Date(date+'T12:00:00').getDay():1,hoursForDay=hours.find(h=>h.day===d)||C.defaults.hours[d],time=select('#time');time.replaceChildren();if(hoursForDay.closed||!settings.booking_enabled)return;const toMin=s=>Number(s.split(':')[0])*60+Number(s.split(':')[1]),duration=parseInt(services[select('#service').value]?.time||60),step=Math.max(5,Number(settings.slot_minutes)||30);for(let mins=toMin(hoursForDay.open);mins+duration<=toMin(hoursForDay.close);mins+=step){const t=String(Math.floor(mins/60)).padStart(2,'0')+':'+String(mins%60).padStart(2,'0');time.add(new Option(t,t))}};
